// ===== Alerte Tally photographe → Telegram =====
// Formulaire « Contact photographe - Emmanuel Ruaudel » (photographe de Rennesdev.fr).
// À faire côté utilisateur :
//  1. Dans Tally → formulaire photographe → Settings → Webhooks → Ajouter :
//     URL de production : https://n8n.rennesdev.fr/webhook/tally-photographe
//  2. Copier la clé de signature de CE webhook (elle commence par "tly-") dans
//     CONFIG.webhookSecret ci-dessous pour activer la vérification.
//  3. Plus tard : ajouter le lien vers l'appli où est stocké le texte du client
//     (constante LIEN_CLIENT ci-dessous).
const CONFIG = {
  LIEN_CLIENT: 'https://tally.so/r/MeX26E', // à remplir plus tard : lien vers l'appli où est stocké le texte du client
  webhookSecret: 'MASQUE', // 🔑 coller ici la clé de signature du webhook Tally du photographe (tly-...)
};

// crypto + en-têtes + signature Tally (en-tête "Tally-Signature", format t=...,v1=...)
let crypto = null;
try { crypto = require('crypto'); } catch { /* non bloquant */ }
const rawHeaders = $json.headers || {};
const headers = {};
for (const [k, v] of Object.entries(rawHeaders)) headers[k.toLowerCase()] = v;
const sigHeader = headers['tally-signature'] || headers['x-tally-signature'];
const bodyRaw = typeof $json.body === 'string' ? $json.body : null;

// --- vérification de la signature Tally (HMAC-SHA256 sur "<t>.<payload>", hexa ou base64 acceptés) ---
let sigOk = null; // null = non vérifiée (secret manquant ou absent), true/false = résultat
if (CONFIG.webhookSecret && crypto && sigHeader) {
  const parties = Object.fromEntries(sigHeader.split(',').map((p) => p.split('=')));
  if (parties.t && parties.v1) {
    const candidats = [JSON.stringify($json.body), ...(bodyRaw ? [bodyRaw] : [])].filter(Boolean);
    sigOk = candidats.some((c) => {
      const base = `${parties.t}.${c}`;
      const hex = crypto.createHmac('sha256', CONFIG.webhookSecret).update(base).digest('hex');
      const b64 = crypto.createHmac('sha256', CONFIG.webhookSecret).update(base).digest('base64');
      return hex === parties.v1 || b64 === parties.v1;
    });
  } else {
    sigOk = false;
  }
}

const body = bodyRaw ? JSON.parse(bodyRaw) : ($json.body || {});
const data = body.data || body || {};
const formName = data.formName || body.formName || 'Contact photographe';
const submissionId = data.submissionId || data.id || '';

// Tally envoie les champs dans data.fields (label + value) — on les affiche s'ils existent
let detail = '';
if (Array.isArray(data.fields)) {
  const lignesChamps = data.fields
    .map((f) => {
      let val = f.value;
      if (Array.isArray(val)) val = val.join(', ');
      if (val === null || val === undefined || val === '') return null;
      const label = f.label || f.id || '';
      return `${label} : ${String(val).slice(0, 200)}`;
    })
    .filter(Boolean)
    .slice(0, 8);
  if (lignesChamps.length) detail = lignesChamps.join('\n');
}

const lignes = [`📸 Nouveau message via Tally — Contact photographe`];
if (formName && formName !== 'Contact photographe') lignes[0] += ` (${formName})`;
lignes.push(`Pour : le photographe de Rennesdev.fr`);
if (submissionId) lignes.push(`Réponse : ${submissionId}`);
if (detail) lignes.push('', detail);
if (CONFIG.LIEN_CLIENT) lignes.push('', `➡️ ${CONFIG.LIEN_CLIENT}`);
lignes.push(`Reçu le ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })}`);
if (sigOk === null && CONFIG.webhookSecret) lignes.push('⚠️ Signature Tally absente du webhook');
else if (sigOk === false) lignes.push('🚨 Signature Tally INVALIDE — requête possiblement falsifiée');

return [{ json: { text: lignes.join('\n') } }];
